def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    my_c = me.count('C')
    opp_d = n - opp_c
    last_opp = opp[-1]

    if n >= 4 and opp_d == n:
        return 'D'
    if n >= 4 and opp_c == n:
        return 'C' if n < 97 else 'D'

    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D' and last_opp == 'D':
        return 'D'

    if last_opp == 'D':
        if opp_c * 2 >= n:
            return 'D' if opp[-2:] == ['D', 'D'] else 'C'
        if n >= 10 and opp_c * 3 >= n:
            return 'C' if rng.random() < 0.35 else 'D'
        return 'D'

    if n >= 95:
        return 'D'

    if opp_d == 0:
        return 'C'

    recent = opp[-12:]
    r_c = recent.count('C')
    r_d = len(recent) - r_c

    if r_c >= 10:
        return 'C'
    if r_d >= 8:
        return 'D'

    if r_c >= 8 and my_c > my_c * 0 + 1:
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    if opp_c * 5 >= n * 4:
        return 'C'

    if opp_c * 3 >= n * 2:
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    if opp_c * 2 >= n:
        return 'C'

    return 'D'
